"""Parsing of structured log lines.

A line has the shape:

    <timestamp> <LEVEL> key=value key="quoted value" ...

The timestamp is an ISO-8601 string. The level is one of DEBUG, INFO, WARN,
ERROR. Fields are key=value pairs separated by spaces; a value may be wrapped
in double quotes when it contains spaces.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable, Iterator

LEVELS = ("DEBUG", "INFO", "WARN", "ERROR")


class ParseError(ValueError):
    """Raised when a line does not match the expected shape."""


@dataclass(frozen=True)
class LogRecord:
    timestamp: str
    level: str
    fields: dict[str, str] = field(default_factory=dict)


def _split_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for token in text.split(" "):
        if not token:
            continue
        if "=" not in token:
            raise ParseError(f"field without '=': {token!r}")
        key, value = token.split("=", 1)
        if value.startswith('"') and value.endswith('"') and len(value) >= 2:
            value = value[1:-1]
        fields[key] = value
    return fields


def parse_line(line: str) -> LogRecord:
    """Parse one log line into a LogRecord.

    Raises ParseError if the line is malformed.
    """
    stripped = line.strip()
    if not stripped:
        raise ParseError("empty line")
    parts = stripped.split(" ", 2)
    if len(parts) < 2:
        raise ParseError(f"expected '<timestamp> <LEVEL> ...', got {line!r}")
    timestamp, level = parts[0], parts[1]
    if level not in LEVELS:
        raise ParseError(f"unknown level {level!r}")
    rest = parts[2] if len(parts) == 3 else ""
    return LogRecord(timestamp=timestamp, level=level, fields=_split_fields(rest))


def parse_lines(lines: Iterable[str]) -> Iterator[LogRecord]:
    """Parse many lines, skipping blank ones."""
    for line in lines:
        if not line.strip():
            continue
        yield parse_line(line)

import pytest

from logparse.parser import ParseError, parse_line, parse_lines


def test_parse_simple_line():
    record = parse_line('2026-09-16T10:00:00Z INFO service=api msg=started')
    assert record.timestamp == "2026-09-16T10:00:00Z"
    assert record.level == "INFO"
    assert record.fields == {"service": "api", "msg": "started"}


def test_parse_line_with_quoted_message():
    record = parse_line('2026-09-16T10:00:01Z WARN service=db msg="slow query" duration_ms=812')
    assert record.level == "WARN"
    assert record.fields == {"service": "db", "msg": "slow query", "duration_ms": "812"}


def test_parse_line_without_fields():
    record = parse_line("2026-09-16T10:00:02Z DEBUG")
    assert record.level == "DEBUG"
    assert record.fields == {}


def test_parse_rejects_unknown_level():
    with pytest.raises(ParseError):
        parse_line("2026-09-16T10:00:03Z LOUD msg=hi")


def test_parse_rejects_empty_line():
    with pytest.raises(ParseError):
        parse_line("   ")


def test_parse_lines_skips_blank_lines():
    lines = [
        "2026-09-16T10:00:00Z INFO service=api msg=started",
        "",
        "2026-09-16T10:00:02Z ERROR service=api status=500",
        "   ",
    ]
    records = list(parse_lines(lines))
    assert [r.level for r in records] == ["INFO", "ERROR"]

