import pytest

from logparse.parser import ParseError, parse_line, parse_lines


def test_parse_simple_line():
    record = parse_line('2026-09-16T10:00:00Z INFO service=api msg=started')
    assert record.timestamp == "2026-09-16T10:00:00Z"
    assert record.level == "INFO"
    assert record.fields == {"service": "api", "msg": "started"}


def test_parse_line_with_quoted_message():
    record = parse_line('2026-09-16T10:00:01Z WARN service=db msg="slow query" duration_ms=812')
    assert record.level == "WARN"
    assert record.fields == {"service": "db", "msg": "slow query", "duration_ms": "812"}


def test_parse_line_without_fields():
    record = parse_line("2026-09-16T10:00:02Z DEBUG")
    assert record.level == "DEBUG"
    assert record.fields == {}


def test_parse_rejects_unknown_level():
    with pytest.raises(ParseError):
        parse_line("2026-09-16T10:00:03Z LOUD msg=hi")


def test_parse_rejects_empty_line():
    with pytest.raises(ParseError):
        parse_line("   ")


def test_parse_lines_skips_blank_lines():
    lines = [
        "2026-09-16T10:00:00Z INFO service=api msg=started",
        "",
        "2026-09-16T10:00:02Z ERROR service=api status=500",
        "   ",
    ]
    records = list(parse_lines(lines))
    assert [r.level for r in records] == ["INFO", "ERROR"]
